<?php
/** TEMP PS S1613 run e3d — D: deploy darbalaukis v3.12 (4 b64 dalys, md5 + token, gyvo failo sargas v3.11.1); T (naujas procesas): LP sekimo simuliacija #35416 per plugino meta (lp-label-created → lp-on-the-way → lp-delivered), gaudyklė prior. 4, skydelis ajax kaip testuotojas, §18.3 sargo šaltinis, Playwright skydelis */
add_action('init', function(){
  if (!isset($_GET['ps_e3d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e3d'])); $o=array('v'=>'S1613 e3d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $c4='';
    $p1=@file_get_contents($bk.'/dl-v312.part1'); $p2=@file_get_contents($bk.'/dl-v312.part2'); $p3=@file_get_contents($bk.'/dl-v312.part3'); $o['parts']=array(strlen((string)$p1),strlen((string)$p2),strlen((string)$p3),strlen($c4));
    $code=base64_decode($p1.$p2.$p3.$c4,true); $o['bytes']=strlen((string)$code); $o['md5']=md5((string)$code);
    if ($o['md5']!=='b20740b6ee0abcc8930a5c1eb0f74246') { $o['STOP']='md5 nesutampa'; $J($o); }
    try { token_get_all($code, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $t=WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'; $o['buvo']=md5_file($t);
    if ($o['buvo']!=='fc4076c7a7152dfd12140b3e33075cc1') { $o['STOP']='gyvas ne v3.11.1 ('.$o['buvo'].')'; $J($o); }
    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v3111-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); @unlink($bk.'/dl-v312.part1'); @unlink($bk.'/dl-v312.part2'); @unlink($bk.'/dl-v312.part3');
  }
  if($f==='T'){
    $o['versija']=Petshop_Darbalaukis::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-darbalaukis.php'); $o['dev_zurnalas_pries']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    update_option('ps_e3_mail',array(),false);
    add_filter('pre_wp_mail',function($r,$a){ $m=get_option('ps_e3_mail',array()); $m[]=array('to'=>is_array($a['to'])?implode(',',$a['to']):$a['to'],'s'=>$a['subject'],'b'=>mb_substr(preg_replace('/\s+/',' ',wp_strip_all_tags((string)$a['message'])),0,420)); update_option('ps_e3_mail',$m,false); return true; },4,2);
    $ID=35416; $BC='CC000000001LT';
    $bk=function($id){ $x=wc_get_order($id); if(!$x) return null; return array('st'=>$x->get_status(),'lp_st'=>(string)$x->get_meta('_woo_lithuaniapost_shipping_status_value'),'bc'=>(string)$x->get_meta('_woo_lithuaniapost_barcode'),'iss'=>(string)$x->get_meta('_ps_dalys_issiusta'),'sek'=>Petshop_Darbalaukis::sekimas($x),'kl'=>array_map(function($s){ return $s['dalis'].' '.$s['busena'].' '.implode('/',$s['numeriai']).' '.$s['vez'].' prist='.$s['pristatyta'].' url='.$s['url']; },Petshop_Darbalaukis::kliento_siuntos($x))); };
    $set=function($id,$st,$bc) { $x=wc_get_order($id); $x->update_meta_data('_woo_lithuaniapost_barcode',$bc); $x->update_meta_data('_woo_lithuaniapost_shipping_status_value',$st); $x->save(); };
    $o['pries']=$bk($ID);
    if($o['pries']['st']!=='processing'){ $o['STOP']='#35416 ne processing'; $J($o); }
    // 1: lipdukas sukurtas (be veiksmo)
    $set($ID,'lp-label-created',$BC); $o['r1']=Petshop_Darbalaukis::venipak_sekimas(array($ID)); $o['r1_po']=$bk($ID); $o['r1_mail']=count(get_option('ps_e3_mail',array()));
    $o['r1_again']=Petshop_Darbalaukis::venipak_sekimas(array($ID));
    // 2: keliauja gavėjui → „Kurjeris paėmė“ pats + laiškas → completed (viena dalis)
    $set($ID,'lp-on-the-way',$BC); $o['r2']=Petshop_Darbalaukis::venipak_sekimas(array($ID)); $o['r2_po']=$bk($ID); $o['r2_mail']=count(get_option('ps_e3_mail',array()));
    $o['r2_again']=Petshop_Darbalaukis::venipak_sekimas(array($ID)); $o['r2_again_mail']=count(get_option('ps_e3_mail',array()));
    // 3: pristatyta
    $set($ID,'lp-delivered',$BC); $o['r3']=Petshop_Darbalaukis::venipak_sekimas(array($ID)); $o['r3_po']=$bk($ID); $o['r3_mail']=count(get_option('ps_e3_mail',array()));
    $o['r3_again']=Petshop_Darbalaukis::venipak_sekimas(array($ID));
    // 4: pilnas cron kandidatų kelias (be ids) — realus Venipak API skaitymas kaip kas 30 min
    $o['r4_cron']=Petshop_Darbalaukis::venipak_sekimas(array()); $o['paskutinis']=get_option('ps_venipak_sekimas_paskutinis');
    $o['notes']=array_map(function($n){ return $n->date_created->date('H:i').' '.mb_substr($n->content,0,220); },array_slice(wc_get_order_notes(array('order_id'=>$ID,'limit'=>6)),0,6));
    $o['ivykiai']=$wpdb->get_results($wpdb->prepare("SELECT veiksmas, kanalas, rezultatas, LEFT(po,160) po FROM {$p}ps_uzsakymu_ivykiai WHERE uzsakymas=%d ORDER BY id DESC LIMIT 5",$ID),ARRAY_A);
    $o['laiskai']=array_map(function($m){ return $m['to'].' | '.$m['s'].' | '.$m['b']; },get_option('ps_e3_mail',array())); delete_option('ps_e3_mail'); $o['dev_zurnalas_po']=count((array)get_option('ps_dev_pastas_zurnalas',array()));
    // §18.3 sargas — kur variklis lygina registruotas siuntas su _ps_shipments (tik skaitymas)
    $o['sargas']=array(); foreach(glob(WPMU_PLUGIN_DIR.'/*.php') as $fi){ if(basename($fi)==='petshop-darbalaukis.php') continue; $ls=file($fi); foreach($ls as $i=>$l){ if(preg_match('/registruota_grupiu|_ps_shipments/',$l)&&preg_match('/completed|status/',$l)){ $o['sargas'][]=basename($fi).':'.($i+1).' '.mb_substr(trim($l),0,220); } } }
    // skydelis per ajax kaip testuotojas
    $tu=get_user_by('login','testuotojas'); $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($tu->ID)->create($exp);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($tu->ID,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($tu->ID,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie($tu->ID,$exp,'logged_in',$tok))));
    wp_set_current_user($tu->ID); $n=wp_create_nonce('ps_dl_zurnalas'); wp_set_current_user(0);
    $r=wp_remote_get(admin_url('admin-ajax.php?action=ps_dl_skydelis&id='.$ID.'&n='.$n),array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $b=is_wp_error($r)?'':wp_remote_retrieve_body($r); $j=json_decode($b,true);
    $o['skydelis']=array('code'=>wp_remote_retrieve_response_code($r),'nr'=>$j['data']['nr']??null,'kur'=>$j['data']['kur']??null,'kl'=>$j['data']['klausimas']??null,'raktai'=>is_array($j['data']??null)?array_keys($j['data']):null);
    $o['cookies']=array(); foreach($cs as $c){ $o['cookies'][]=array('name'=>$c->name,'value'=>$c->value); }
    $o['shots']=array(array('n'=>'s1613_e3_skydelis_35416','u'=>admin_url('admin.php?page=ps-desk&eile=visi&atidaryti='.$ID),'w'=>1400,'full'=>false,'eval'=>"({sk:(document.querySelector('#skydelis,.dl-skydelis,.dl-sk')||document.body).innerText.replace(/\\s+/g,' ').slice(0,900)})"));
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
  $J($o);
},99);
